/* OBRASST · las cartillas doble cara con QR de los equipos (24/11/2026). El motor (CARTILLAS-EQ-MOTOR) es el mismo de la app. */
/* >>> CARTILLAS-EQ-MOTOR-INI (24/11/2026 · lo mismo en la app y en portal/cartillas-equipos.js; copias.py revisa que no se separen) <<< */
/* ══════════════════════════════════════════════════════════════════
   CARTILLAS DOBLE CARA CON QR (24/11/2026)
   Marcelo (prompt «Cartillas doble cara con QR para equipos, andamios,
   maquinaria y herramientas»): la cara A identifica el equipo (logo,
   código, peligros, EPP, uso seguro y su QR /h/); la cara B la elige el
   supervisor entre bloques útiles en obra, sin checklists diarios (el
   antes de usar se registra escaneando el QR; los 12 meses, solo donde la
   revisión es mensual). Tres tamaños reales: media hoja A4 (2 por hoja),
   tag de 95 × 135 mm (4) y mini-tag de 65 × 95 mm (8), en un PDF a doble
   cara: el reverso va con las columnas al revés para que cada cara B
   calce detrás de su cara A al cortar.
   Datos técnicos (corregidos del prompt, «nada que no sea cierto»): las
   clases de carga de andamios son las de la EN 12811-1; las distancias a
   líneas eléctricas, las de la tabla A de OSHA 1926.1408; las señales,
   las de ASME B30.5; la distancia libre de una línea con absorbedor va
   con valores típicos y dice que mandan los del fabricante.
   Cada cara se dibuja en un lienzo a 10 px por mm (con las letras y el QR
   de los carteles: _cqAjustar, qrePintar) y el PDF las pone a su medida.
   Lo que elige el supervisor para cada equipo vive en la obra, sin tocar
   la tabla de equipos: sst_estado «cartillas_eq» = { v:1, e:{ <id del
   equipo>:{ f, t, r:[…], img, alt, carga, anc, cap, mod } }, mod:[{ id,
   n, url }] } (mod: las modulaciones de andamio que sube la obra; cada
   andamio elige la suya y sale a toda la cara B).
   25/11/2026 · Marcelo: «más imagen y menos letras, pero entendible… igual
   que el de extintores y mejor»: la cara A va como su cartel (cabecera
   con la señal, el código grande, el QR en su marco y la franja de la
   obra), con las señales de la NTP para los peligros y el EPP y las
   reglas en baldosas numeradas.
   ══════════════════════════════════════════════════════════════════ */
var CEQ_K = 10;   /* px por mm */
var CEQ_CLAVE = 'cartillas_eq';
/* w, h: la cartilla (mm); en la hoja A4 (apaisada o vertical) van cols × filas */
var CEQ_FMT = {
  /* 25/11/2026 · el cartel A4 (una por hoja): su cara A es el cartel del equipo; su cara B, la de la cartilla a escala */
  a4:  { k:'a4', n:'A4', d:'21 × 29,7 cm · 1 por hoja', w:210, h:297, cols:1, filas:1, apaisada:false, micro:false, rev:2 },
  a5:  { k:'a5', n:'A5', d:'14 × 19,8 cm · 2 por hoja A4', w:140, h:198, cols:2, filas:1, apaisada:true, micro:false, rev:2 },
  tag: { k:'tag', n:'Tag de herramienta', d:'9,5 × 13,5 cm · 4 por hoja A4', w:95, h:135, cols:2, filas:2, apaisada:false, micro:true, rev:1 },
  mini:{ k:'mini', n:'Mini-tag', d:'6,5 × 9,5 cm · 8 por hoja A4', w:65, h:95, cols:4, filas:2, apaisada:true, micro:true, rev:1 }
};
/* 25/11/2026 · «Ahora sección de carteles» (Marcelo): los seis carteles que se imprimen, en vez de las etiquetas.
   [clave, nombre, medida, formato, doble cara] */
var CEQ_MODOS = [
  ['a4', 'Cartel A4', '21 × 29,7 cm · 1 por hoja · una cara', 'a4', false],
  ['a4d', 'Cartel A4 doble cara', '21 × 29,7 cm · 1 por hoja · atrás, su checklist o lo que elijas', 'a4', true],
  ['a5', 'Cartel A5', '14 × 19,8 cm · 2 por hoja A4 · una cara', 'a5', false],
  ['a5d', 'Cartel A5 doble cara', '14 × 19,8 cm · 2 por hoja A4 · a doble cara', 'a5', true],
  ['tag', 'Tag de herramienta', '9,5 × 13,5 cm · 4 por hoja A4 · a doble cara', 'tag', true],
  ['mini', 'Mini-tag', '6,5 × 9,5 cm · 8 por hoja A4 · a doble cara', 'mini', true]
];
function ceqModoDef(k){ var r = CEQ_MODOS[0]; CEQ_MODOS.forEach(function(m){ if(m[0] === k) r = m; }); return { k:r[0], n:r[1], d:r[2], t:r[3], dc:r[4] }; }
/* el modo de lo elegido (formato y doble cara) */
function ceqModo(c){ c = c || {}; if(c.t === 'a4') return c.dc ? 'a4d' : 'a4'; if(c.t === 'a5') return c.dc === false ? 'a5' : 'a5d'; return CEQ_FMT[c.t] ? c.t : 'a4'; }
/* el extintor y el botiquín: su A4 doble cara lleva atrás el cuadro de los 12 meses (cartelReversoEquipo) */
function ceqConRev(x){ return typeof eqConReverso === 'function' && !!eqConReverso(x && x.tipo); }
/* si ese equipo puede salir en ese cartel: el A4 de una cara, todos; los demás, con su familia */
function ceqPuede(x, c, m){ var M = ceqModoDef(m); if(M.t === 'a4' && (!M.dc || ceqConRev(x))) return true; return !!CEQ_FAM[c && c.f]; }
