      if(c.dc && c.r[0] === 'modulacion') h += '<div class="campo"><label for="pct-mod">Su modulación <span class="gris-t">(toda la cara B)</span></label><select id="pct-mod"><option value="">' + (PCT.mod.length ? '— elige —' : 'La obra aún no subió modulaciones') + '</option>' +
        PCT.mod.map(function(m2){ return '<option value="' + esc(m2.id) + '"' + (c.mod === m2.id ? ' selected' : '') + '>' + esc(m2.n) + '</option>'; }).join('') + '</select>' +
        '<p class="ayuda"><button type="button" class="bt-link" id="pct-mod-nueva">＋ Subir una modulación</button> · las de la obra se ven en «Carteles» › «Modulaciones de andamio».</p></div>';
